namespace{
int checks=0;
void check(bool ok,const char* why){if(!ok)throw std::runtime_error(why);++checks;}
void events(){QApplication::processEvents();QApplication::sendPostedEvents(nullptr,QEvent::DeferredDelete);QTest::qWait(20);}
void valid(const Document& d){validate(d);check(decode(encode(d))==d,"Independent full caller native-valid BEFORE Window");}
void same(const Session& a,const Session& b){check(a.document()==b.document()&&encode(a.document())==encode(b.document())&&a.preview_document()==b.preview_document()&&a.history()==b.history()&&a.revision()==b.revision()&&a.gesture_active()==b.gesture_active()&&a.gesture_generation()==b.gesture_generation(),"Entire caller Session/native/History/preview/revision/generation unchanged");}
void write(const QString& path,const Document& d){QFile f(path);const auto b=encode(d);check(f.open(QIODevice::WriteOnly|QIODevice::NewOnly)&&f.write(b.data(),b.size())==static_cast<qint64>(b.size()),"Immutable actual or independent native retained once");}
QByteArray read(const QString& path){QFile f(path);check(f.open(QIODevice::ReadOnly),"Owned native bytes readable");return f.readAll();}
template<class T>T* control(Window& w,const QString& name){for(auto* c:w.findChildren<T*>(name))if(c->isVisible())return c;throw std::runtime_error("Original visible source producer missing");}
void reveal(QWidget* c){QPointer<QWidget> alive=c;for(auto* p=c->parentWidget();p;p=p->parentWidget())if(auto* s=qobject_cast<QScrollArea*>(p))s->ensureWidgetVisible(c);events();check(alive&&alive->isVisible()&&alive->isEnabled(),"Original source producer survives reveal and is enabled");}

Document fixture(bool remove){auto d=empty_document("collection-membership-document","comp","art");auto& board=d.compositions.front().artboards.front();board.width=640;board.height=480;for(const auto& id:{Id{"shape"},Id{"peer"},Id{"other"}}){Object o;o.id=id;o.name=id=="shape"?"Original source":id;o.source=default_primitive(id+"-source","nect.shape.rectangle");o.source->parameters.at("width").literal=80;o.source->parameters.at("height").literal=60;o.source->parameters.at("center_x").literal=id=="shape"?320:id=="peer"?180:460;o.source->parameters.at("center_y").literal=240;auto fill=default_operation(id+"-fill","nect.paint.fill");fill.parameters.at("r").literal=id=="shape"?1:0;fill.parameters.at("g").literal=id=="other"?1:0;fill.parameters.at("b").literal=id=="peer"?1:0;o.stack={fill};d.objects.emplace(id,o);d.compositions.front().roots.push_back(id);}Collection c;c.id="collection";c.name="Existing collection";c.members={"peer"};if(remove)c.members.push_back("shape");d.collections={c};return d;}
void flow(const QString& root,int mode){const bool remove=mode>=5,success=mode==4||mode==6,foreign_case=mode==0||mode==5;auto initial=fixture(remove);valid(initial);auto current=initial;current.objects.at("shape").name="Current source";valid(current);Session base(initial);base.apply({Rename{"shape","Current source"}},0);check(base.document()==current&&base.revision()==1,"Complete non-owning membership/artwork/source native/History BEFORE Window");auto foreign_initial=initial;foreign_initial.id="foreign-membership-document";foreign_initial.objects.at("shape").source->parameters.at("height").literal=90;foreign_initial.collections.front().members.insert(foreign_initial.collections.front().members.begin(),"other");valid(foreign_initial);auto foreign_current=foreign_initial;foreign_current.objects.at("shape").name="Current source";valid(foreign_current);Session foreign(foreign_initial);foreign.apply({Rename{"shape","Current source"}},0);check(foreign.document()==foreign_current&&foreign.revision()==base.revision()&&foreign.gesture_generation()==base.gesture_generation(),"Independent foreign source IDs/counters and caller-only membership BEFORE Window");auto concurrent=base;concurrent.apply({Rename{"shape","Concurrent source"}},1);auto concurrent_doc=current;concurrent_doc.objects.at("shape").name="Concurrent source";valid(concurrent_doc);check(concurrent.document()==concurrent_doc,"Whole concurrent caller BEFORE Window");auto busy=base;busy.begin_gesture(1);busy.update_gesture({Set{{"shape","","generator.height"},90}});auto preview=current;preview.objects.at("shape").source->parameters.at("height").literal=90;valid(preview);check(busy.document()==current&&busy.preview_document()==preview,"Independent whole active artwork preview BEFORE Window");auto transformed=current;if(remove)transformed.collections.front().members={"peer"};else transformed.collections.front().members={"peer","shape"};valid(transformed);auto committed=base;committed.apply({CollectionCommand{SetCollectionMembers{"collection",transformed.collections.front().members}}},1);check(committed.document()==transformed&&committed.document().objects==current.objects&&committed.document().compositions==current.compositions,"Whole independent exact membership delta matches typed command, all artwork/hierarchy unchanged BEFORE Window");auto history=committed;history.undo(2);check(history.document()==current,"Whole membership Undo BEFORE Window");history.redo(3);check(history.document()==transformed&&history.history()==committed.history(),"One History/full Redo BEFORE Window");auto expected=base;if(foreign_case)expected=foreign;else if(mode==2)expected=concurrent;else if(mode==3)expected=busy;else if(success)expected=committed;const auto prefix=root+"/mode-"+QString::number(mode);write(prefix+"-expected.nect",expected.document());write(prefix+"-expected-preview.nect",expected.preview_document());
QSettings settings(prefix+"-settings.ini",QSettings::IniFormat);settings.setFallbacksEnabled(false);Window w(prefix+"-recovery",std::make_unique<FolderLibrary>(settings,FolderLibrary::PersistOverride{},FolderLibrary::ReadbackOverride{},prefix+"-assets"),&settings);w.host.session=base;w.host.edited();w.resize(1400,1050);w.show();events();w.canvas->set_active_artboard("comp","art",false);w.canvas->set_selection("shape","");events();auto* actor=w.findChild<QAction*>(remove?"remove-selection-from-collection":"add-selection-to-collection");check(actor&&actor->isEnabled(),"Original Collection membership action enabled");const auto original_host=w.host.session_id;QString callback_error;int stages=0;QTimer::singleShot(0,&w,[&]{try{auto* dialog=qobject_cast<QInputDialog*>(QApplication::activeModalWidget());check(dialog&&dialog->windowTitle()==(remove?"Remove from Collection":"Add to Collection"),"Original membership choose modal exact");++stages;check(dialog->textValue().contains("collection")&&dialog->textValue().contains("Existing collection"),"Original stable Collection ID/source row captured");if(foreign_case)w.host.session=foreign;else if(mode==1)w.host.session_id+="-changed";else if(mode==2)w.host.session=concurrent;else if(mode==3)w.host.session=busy;check(dialog->grab().save(prefix+"-dialog.png"),"Actual original membership modal BEFORE acceptance");dialog->accept();}catch(const std::exception& e){callback_error=QString::fromUtf8(e.what());if(auto* dialog=qobject_cast<QDialog*>(QApplication::activeModalWidget()))dialog->reject();}});actor->trigger();events();check(callback_error.isEmpty()&&stages==1,"Original membership invocation completes without fixture exception");const auto observed=w.host.session;const auto status=w.statusBar()->currentMessage();write(prefix+"-observed.nect",observed.document());write(prefix+"-observed-preview.nect",observed.preview_document());check(w.grab().save(prefix+"-window.png"),"Original result BEFORE Save");QJsonObject v{{"mode",mode},{"status",status},{"document_equal",observed.document()==expected.document()},{"preview_equal",observed.preview_document()==expected.preview_document()},{"history_equal",observed.history()==expected.history()},{"artwork_equal",observed.document().objects==expected.document().objects&&observed.document().compositions==expected.document().compositions},{"revision",qint64(observed.revision())},{"gesture_active",observed.gesture_active()},{"gesture_generation",qint64(observed.gesture_generation())},{"caller_identity_preserved",mode!=3||observed.gesture_identity()==busy.gesture_identity()},{"host_equal",mode==1?w.host.session_id!=original_host:w.host.session_id==original_host},{"view_equal",w.canvas->selected_object=="shape"&&w.canvas->selected_point.empty()&&w.canvas->active_composition()=="comp"&&w.canvas->active_artboard()=="art"},{"save_intent",mode!=3}};QFile metadata(prefix+"-producer.json");check(metadata.open(QIODevice::WriteOnly|QIODevice::NewOnly),"Immutable whole membership/artwork/native/History readback BEFORE Save");metadata.write(QJsonDocument(v).toJson());metadata.close();same(observed,expected);check(v["view_equal"].toBool()&&v["host_equal"].toBool()&&v["caller_identity_preserved"].toBool()&&v["artwork_equal"].toBool(),"Caller selection/token/artwork/hierarchy unchanged");if(mode==0||mode==1||mode==2||mode==5)check(status.startsWith("REVISION_CONFLICT:"),"Document/Host/revision membership refusal explicit");if(mode==3)check(status.startsWith("GESTURE_ACTIVE:"),"Active caller refusal explicit");if(success){check(status.startsWith(remove?"Selected Objects removed from Collection":"Selected Objects added to Collection"),"Current non-owning membership success explicit");w.host.session.undo(2);check(w.host.session.document()==current,"Actual accepted full membership Undo");w.host.session.redo(3);check(w.host.session.document()==transformed,"Actual accepted full membership Redo");w.host.session=observed;}if(mode!=3){w.host.save(prefix+"-saved.nect");w.host.flush();events();same(w.host.session,expected);check(read(prefix+"-saved.nect")==read(prefix+"-expected.nect")&&QFile::copy(prefix+"-saved.nect",prefix+"-snapshot.nect"),"Whole exact membership/artwork native Save/snapshot, no normalization");}w.close();events();}
}
int main(int argc,char** argv){qputenv("QT_QPA_PLATFORM","windows");QApplication app(argc,argv);app.setStyle("Fusion");app.setStyleSheet(application_style_sheet());std::cout.setf(std::ios::unitbuf);try{std::cout<<"Native platform="<<QGuiApplication::platformName().toStdString()<<" PID="<<QCoreApplication::applicationPid()<<" original Collection Add/Remove membership; physical/clipboard/fonts NOT_RUN\n";QTemporaryDir temp;check(temp.isValid(),"Owned scratch valid");const auto requested=qEnvironmentVariable("NECT_COLLECTION_MEMBERSHIP_DOCUMENT_ROOT"),root=requested.isEmpty()?temp.path():requested;int failures=0;for(int mode=0;mode<7;++mode){try{flow(root,mode);std::cout<<"CASE PASS mode="<<mode<<"\n";}catch(const std::exception& e){++failures;std::cerr<<"CASE FAIL mode="<<mode<<" reason="<<e.what()<<" checks="<<checks<<"\n";}}if(failures)throw std::runtime_error("Collection membership Document cases failed: "+std::to_string(failures));std::cout<<"PASS Collection membership Document "<<checks<<" checks\n";QTest::qWait(300);return 0;}catch(const std::exception& e){std::cerr<<"FAIL Collection membership Document "<<e.what()<<" after "<<checks<<" checks\n";QTest::qWait(300);return 1;}}
